import React, { useEffect, useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

export default function Users() {
  const [users, setUsers] = useState([]);
  const [errorMsg, setErrorMsg] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
    } else {
      fetchUsers(token);
    }
  }, [navigate]);

  const fetchUsers = async (token) => {
    try {
      const res = await axios.get("http://127.0.0.1:5000/users", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setUsers(res.data);
    } catch (err) {
      console.error(err);
      setErrorMsg("Nu s-au putut încărca utilizatorii. Verifică serverul.");
    }
  };

  const deleteUser = async (id) => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }

    try {
      await axios.delete(`http://127.0.0.1:5000/users/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setUsers(users.filter((u) => u.id !== id));
    } catch (err) {
      console.error(err);
      setErrorMsg("Nu s-a putut șterge utilizatorul. Verifică serverul.");
    }
  };

  return (
    <div className="page-container dark-bg">
      <h1>Utilizatori</h1>

      {errorMsg && <div className="error-box">{errorMsg}</div>}

      <div className="actions-bar">
        <Link to="/add-user">
          <button className="button primary-btn">Adaugă utilizator</button>
        </Link>
      </div>

      <div className="table-wrapper light-bg">
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Username</th>
              <th>Email</th>
              <th>Telefon</th>
              <th>Adresă</th>
              <th>Acțiuni</th>
            </tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>{u.username}</td>
                <td>{u.email}</td>
                <td>{u.phone}</td>
                <td>{u.address}</td>
                <td className="actions-cell">
                  <Link to={`/edit-user/${u.id}`}>
                    <button className="button small-btn">Editează</button>
                  </Link>
                  <button
                    className="button delete-btn"
                    onClick={() => deleteUser(u.id)}
                  >
                    Șterge
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
